#include <vector>
#include <cstddef>
#include <omp.h>

void gemv(std::vector<double> const& A, std::vector<double> const& x, std::vector<double> &y, size_t M, size_t N) {
    // Ensure output has the correct size
    y.assign(M, 0.0);

    // Basic bounds safety: only process what is valid in provided buffers
    const size_t maxRowsFromA = (N == 0) ? 0 : (A.size() / N);
    const size_t rows = (M < maxRowsFromA) ? M : maxRowsFromA;
    const size_t cols = (x.size() < N) ? x.size() : N;

    #pragma omp parallel for schedule(static)
    for (std::ptrdiff_t i = 0; i < static_cast<std::ptrdiff_t>(rows); ++i) {
        double sum = 0.0; // private accumulator per iteration/thread
        const size_t rowOffset = static_cast<size_t>(i) * N;
        for (size_t j = 0; j < cols; ++j) {
            sum += A[rowOffset + j] * x[j];
        }
        y[static_cast<size_t>(i)] = sum; // each thread writes distinct y[i]
    }
}
